    <div class="player-panel"><div class="player-role-icon" id="player-icon"></div><div class="player-information"><div><strong id="player-name"></strong><span id="player-role"></span></div><div class="player-health"><div id="player-health-fill"></div></div><div class="player-guard" id="player-guard" title="ガードゲージ"><div id="player-guard-fill"></div></div><span class="health-label" id="health-label"></span></div><button id="switch" class="switch-button" aria-label="次の味方に切り替え">${L(`people`)}<small>切替</small></button></div>
